local root,vectors,adapter=assert(arg[1]),assert(arg[2]),assert(arg[3]);package.path=root.."/?.lua;";local Seme=dofile(adapter);_G.Seme=Seme;local state=require("state");local f=assert(io.open(vectors,"r"));local data=vim.json.decode(f:read("*a"));f:close();local valid,rejected={},{}
local function decode(item)local count=item.arguments[1].fields.Count;if not count or count.kind~="i64"then error("native.invalid_v1")end;return Seme.record("V1",{"Count"},{Count=Seme.i64_literal(count.i64)})end
local function encode(value)local payload=Seme.result_value(value);return{kind="result",variant="ok",payload={kind="record",fields={Count={kind="i64",i64=Seme.i64_decimal(Seme.field(payload,"Count"))},Namespace={kind="text",text=Seme.text_string(Seme.field(payload,"Namespace"))}}}}end
for _,item in ipairs(data.valid)do valid[item.name]=encode(state.MigrateV1ToV2(decode(item)))end;for _,item in ipairs(data.malformed)do local ok=pcall(function()return state.MigrateV1ToV2(decode(item))end);assert(not ok,item.name);rejected[item.name]=true end;io.write(vim.json.encode({valid=valid,malformed=#data.malformed,rejected=rejected}),"\n")
